import { z } from "zod";
import { orgIdSchema, pageRequestSchema, projectIdSchema } from "./common";

export const searchSubjectKindSchema = z.enum(["issue", "comment", "project"]);

export const searchQuerySchema = z
  .object({
    orgId: orgIdSchema,
    q: z.string().min(1, "type something to search").max(200),
    kinds: z.array(searchSubjectKindSchema).default(["issue"]),
    projectId: projectIdSchema.optional(),
  })
  .extend(pageRequestSchema.shape);

export const reindexRequestSchema = z.object({
  orgId: orgIdSchema,
  subjectKind: searchSubjectKindSchema,
  subjectId: z.string().min(1),
});

export type SearchQueryInput = z.infer<typeof searchQuerySchema>;
export type ReindexRequestInput = z.infer<typeof reindexRequestSchema>;
import { z } from "zod";

/**
 * Coercions for reading pagination out of `searchParams`. Remember that in
 * Next 16 `searchParams` is a Promise — `await` it before parsing.
 */
export const searchParamsPaginationSchema = z.object({
  page: z.coerce.number().int().min(1).catch(1),
  perPage: z.coerce.number().int().min(1).max(100).catch(25),
  cursor: z.string().optional(),
});

export const searchParamsSortSchema = z.object({
  sort: z.string().max(40).optional(),
  dir: z.enum(["asc", "desc"]).catch("desc"),
});

export function toOffset(page: number, perPage: number): number {
  return (page - 1) * perPage;
}

export type SearchParamsPagination = z.infer<
  typeof searchParamsPaginationSchema
>;
export type SearchParamsSort = z.infer<typeof searchParamsSortSchema>;
