/**
 * Rebuilds the search index for one organization; used after a bulk import or an index drift alarm.
 *
 * Must call (do not reimplement): indexIssue, indexComment, indexProject
 */
import { createLogger } from "@/lib/logger";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as searchRepo from "@/server/repositories/search-repository";
import {
  indexComment,
  indexIssue,
  indexProject,
} from "@/server/services/search-service";
import { runJob } from "./types";
import type { JobResult } from "@/server/jobs/types";
import type { OrgId, Page } from "@/types/common";

/** Rows read per page while walking the org's content. */
const PAGE_SIZE = 100;

const logger = createLogger("search-reindex-job");

/** Yields every row of a cursor-paged listing, however many pages it spans. */
async function* eachRow<T>(
  fetchPage: (cursor: string | null) => Promise<Page<T>>,
): AsyncGenerator<T> {
  let cursor: string | null = null;
  do {
    const page = await fetchPage(cursor);
    yield* page.items;
    cursor = page.nextCursor;
  } while (cursor !== null);
}

/**
 * Walks one tenant's projects, issues and comments and re-upserts every
 * document the search rule allows, then deletes whatever else the index holds
 * for that tenant. Scoped to a single org on purpose: a full-fleet reindex is
 * a sequence of these, so one slow tenant cannot stall the rest.
 *
 * Archived rows are read too, but only so the index writers can clear them:
 * they own the "is this searchable?" decision, and a subtree whose root is not
 * searchable is not walked any further. Every page of every listing is
 * followed, so the size of the workspace does not change the outcome.
 *
 * The clean-up needs the complete picture of what is allowed, so it is skipped
 * when any document failed to index — a partial walk must never delete an
 * entry that only looked stale because its parent could not be processed.
 */
export async function runSearchReindexJob(orgId: OrgId): Promise<JobResult> {
  return runJob("search-reindex", async (result) => {
    const kept = new Set<string>();

    const record = (kind: "project" | "issue" | "comment", id: string) => {
      kept.add(searchRepo.documentKey(kind, id));
      result.processed += 1;
    };

    const projects = eachRow((cursor) =>
      projectRepo.listProjects({
        orgId,
        limit: PAGE_SIZE,
        cursor,
        includeArchived: true,
      }),
    );

    for await (const project of projects) {
      try {
        if (!(await indexProject(orgId, project))) continue;
        record("project", project.id);
      } catch (error) {
        result.failed += 1;
        logger.error("failed to index project", {
          projectId: project.id,
          reason: error instanceof Error ? error.message : String(error),
        });
        continue;
      }

      const issues = eachRow((cursor) =>
        issueRepo.listIssues({
          orgId,
          projectId: project.id,
          limit: PAGE_SIZE,
          cursor,
          includeArchived: true,
        }),
      );

      for await (const issue of issues) {
        try {
          if (!(await indexIssue(orgId, issue))) continue;
          record("issue", issue.id);
        } catch (error) {
          result.failed += 1;
          logger.error("failed to index issue", {
            issueId: issue.id,
            reason: error instanceof Error ? error.message : String(error),
          });
          continue;
        }

        const comments = eachRow((cursor) =>
          commentRepo.listComments({
            orgId,
            issueId: issue.id,
            includeArchived: true,
            limit: PAGE_SIZE,
            cursor,
          }),
        );

        for await (const comment of comments) {
          try {
            if (await indexComment(orgId, comment)) {
              record("comment", comment.id);
            }
          } catch (error) {
            result.failed += 1;
            logger.error("failed to index comment", {
              commentId: comment.id,
              reason: error instanceof Error ? error.message : String(error),
            });
          }
        }
      }
    }

    if (result.failed > 0) {
      logger.warn("skipping stale-entry clean-up after indexing failures", {
        orgId,
        failed: result.failed,
      });
      return;
    }

    const removed = await searchRepo.deleteDocumentsOutside(orgId, kept);
    if (removed > 0) {
      logger.info("removed stale search entries", { orgId, removed });
    }
  });
}

