/**
 * The search rule across archive/restore, later writes and the rebuild job:
 * a project is found while live; an issue while it and its project are live;
 * a comment while it, its issue and that issue's project are live.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
vi.mock("@/lib/rate-limit", async () => (await import("../server/_support/doubles/misc")).rateLimitModule);

import { runSearchReindexJob } from "@/server/jobs/search-reindex-job";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as searchRepo from "@/server/repositories/search-repository";
import * as commentService from "@/server/services/comment-service";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import * as searchService from "@/server/services/search-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { Unsubscribe } from "@/types/event";

let cleanup: () => void;
let detach: Unsubscribe;
let tenant: Tenant;
let counter = 0;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  detach = searchService.registerSearchListeners();
  tenant = await createTenant("searchlife", "growth");
});

afterAll(() => {
  detach();
  cleanup();
});

afterEach(() => {
  counter += 1;
});

async function found(q: string, kinds: ("issue" | "comment" | "project")[] = ["issue", "comment", "project"]) {
  const page = await searchService.search(tenant.actors.member, {
    orgId: tenant.org.id,
    q,
    kinds,
    limit: 25,
    cursor: null,
  });
  expect(page.items).toHaveLength(page.total);
  return page.items.map((hit) => `${hit.kind}`).sort();
}

async function makeProject(tag: string) {
  return projectService.createProject(tenant.actors.admin, {
    orgId: tenant.org.id,
    name: `Proj ${tag}`,
    slug: `proj-${tag.toLowerCase()}`,
    key: `P${tag.slice(0, 4).toUpperCase()}`,
    description: null,
    visibility: "org",
    leadId: null,
    color: "#6366f1",
    targetDate: null,
  });
}

async function makeIssue(projectId: Tenant["project"]["id"], title: string) {
  return issueService.createIssue(
    tenant.actors.member,
    issueInput(tenant.org.id, projectId, { title }),
  );
}

async function makeComment(issueId: Parameters<typeof commentService.createComment>[1]["issueId"], body: string) {
  return commentService.createComment(tenant.actors.member, {
    orgId: tenant.org.id,
    issueId,
    body,
    parentId: null,
    mentionedUserIds: [],
  });
}

describe("archiving an issue", () => {
  it("takes its comments out of search too", async () => {
    const issue = await makeIssue(tenant.project.id, "IssArchA thing");
    await makeComment(issue.id, "IssArchA remark");
    expect(await found("IssArchA")).toEqual(["comment", "issue"]);

    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, issue.id);
    expect(await found("IssArchA")).toEqual([]);
  });
});

describe("archiving a project", () => {
  it.each([true, false])("hides its subtree when archiveIssues is %s", async (archiveIssues) => {
    const tag = `Arch${archiveIssues ? "Yes" : "No"}`;
    const project = await makeProject(tag);
    const issue = await makeIssue(project.id, `${tag}Zed issue`);
    await makeComment(issue.id, `${tag}Zed comment`);
    expect(await found(`${tag}Zed`)).toEqual(["comment", "issue"]);

    await projectService.archiveProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      projectId: project.id,
      archiveIssues,
    });
    expect(await found(`${tag}Zed`)).toEqual([]);
    expect(await found(`Proj ${tag}`)).toEqual([]);
  });

  it("keeps later comments and edits of kept issues hidden", async () => {
    const project = await makeProject("Kept");
    const issue = await makeIssue(project.id, "KeptOne issue");
    const comment = await makeComment(issue.id, "KeptOne early");
    await projectService.archiveProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      projectId: project.id,
      archiveIssues: false,
    });

    await makeComment(issue.id, "KeptOne late");
    await issueService.updateIssue(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      title: "KeptOne retitled",
    });
    await commentService.updateComment(tenant.actors.member, {
      orgId: tenant.org.id,
      commentId: comment.id,
      body: "KeptOne edited",
    });
    expect(await found("KeptOne")).toEqual([]);
  });
});

describe("restoring a project", () => {
  it("brings back the project, kept issues and their comments only", async () => {
    const project = await makeProject("Rest");
    const early = await makeIssue(project.id, "RestQ early-archived");
